-- Задачи мастер-плана: №, этап, блок, описание, срок, стоимость, роли (через «|»)
CREATE TEMP TABLE "_mp" ("number" INT, "stage" TEXT, "block" TEXT, "description" TEXT, "termText" TEXT, "cost" INT, "roles" TEXT);

-- Добавляем только отсутствующие номера; порядок — сразу за последней задачей шаблона
DELETE FROM "_mp" m WHERE EXISTS (SELECT 1 FROM "TemplateTask" t WHERE t."number" = m."number");

SELECT m."number", s."id", b."id", m."description", m."termText", m."cost",
       COALESCE((SELECT MAX("order") FROM "TemplateTask"), 0)
         + ROW_NUMBER() OVER (ORDER BY m."number")
FROM "_mp" m
LEFT JOIN "Stage" s ON s."name" = m."stage"
LEFT JOIN "Block" b ON b."name" = m."block";

-- Роли только что добавленных задач (в "_mp" остались лишь они)
SELECT DISTINCT r."id", t."id"
FROM "_mp" m
JOIN "TemplateTask" t ON t."number" = m."number"
CROSS JOIN LATERAL unnest(string_to_array(m."roles", '|')) AS rn(name)
JOIN "Role" r ON r."name" = rn.name
WHERE m."roles" <> ''
ON CONFLICT DO NOTHING;

DROP TABLE "_mp";
