INSERT INTO "TermPhrase" ("text", "order")
INSERT INTO "_mp" VALUES
  (1, '1. Предстартовая подготовка', 'Концепция и стратегия', 'Анализ целевой аудитории: сегментация, потребности, ожидания от участия', 'до старта продаж', 0, 'Маркетинг'),
  (2, '1. Предстартовая подготовка', 'Концепция и стратегия', 'Сформировать уникальное торговое предложение (УТП) и позиционирование форума', 'до старта продаж', 0, 'Маркетинг'),
  (3, '1. Предстартовая подготовка', 'Концепция и стратегия', 'Утвердить рабочее название и дату(ы) проведения форума', 'до старта продаж', 0, 'Маркетинг'),
  (4, '1. Предстартовая подготовка', 'Концепция и стратегия', 'Сформировать тему и основной посыл (ключевое сообщение) форума', 'до старта продаж', 0, 'Программа|Маркетинг'),
  (5, '1. Предстартовая подготовка', 'Концепция и стратегия', 'Согласовать концепцию мероприятия, включая архитектуру мероприятия в целом', 'до старта продаж', 0, 'Ивент'),
  (6, '1. Предстартовая подготовка', 'Финансы и бюджет', 'Разработать предварительную смету (бюджет) мероприятия', 'до старта продаж', 0, 'Финансы'),
  (7, '1. Предстартовая подготовка', 'Финансы и бюджет', 'Сформировать предварительную финансовую модель форума, включая план продаж', 'до старта продаж', 0, 'Финансы'),
  (8, '1. Предстартовая подготовка', 'Финансы и бюджет', 'Определить % билетов для бесплатного распространения и категории получателей', 'до старта продаж', 0, 'Финансы|Отдел продаж'),
  (9, '1. Предстартовая подготовка', 'Финансы и бюджет', 'Рассчитать максимальную вместимость площадки для целей финансовой модели и планирования продаж', 'до старта продаж', 0, 'Ивент|Финансы'),
  (10, '1. Предстартовая подготовка', 'Финансы и бюджет', 'Сформулировать техническое задание на приглашение бесплатных участников (критерии, условия)', 'до старта продаж', 0, 'Отдел продаж'),
  (11, '1. Предстартовая подготовка', 'Финансы и бюджет', 'Определить этапы и график повышения цен на билеты (тарифная сетка по периодам)', 'до старта продаж', 0, 'Финансы|Отдел продаж'),
  (12, '1. Предстартовая подготовка', 'Юридические вопросы', 'Актуализировать типовые формы договоров (с партнерами, подрядчиками, спикерами, модераторами)', 'до старта продаж', 0, 'Юрист'),
  (13, '1. Предстартовая подготовка', 'Площадка', 'Сформировать и разослать запросы в отели / площадки / DMC-агентства', 'до старта продаж', 0, 'Ивент'),
  (14, '1. Предстартовая подготовка', 'Площадка', 'Получить и сравнить сметы от подрядчиков площадки, оптимизировать смету', 'до старта продаж', 0, 'Ивент'),
  (15, '1. Предстартовая подготовка', 'Площадка', 'Провести инспекционный визит на выбранную(ые) площадку(и)', 'до старта продаж', 60000, 'Ивент'),
  (16, '1. Предстартовая подготовка', 'Площадка', 'Выбрать площадку и подрядчика, согласовать условия сотрудничества', 'до старта продаж', 1500000, 'Ивент'),
  (17, '1. Предстартовая подготовка', 'Площадка', 'Зафиксировать в договоре штрафные и аннуляционные санкции площадки', 'до старта продаж', 0, 'Ивент|Юрист'),
  (18, '1. Предстартовая подготовка', 'Партнерства', 'Разработать партнерские (спонсорские) пакеты: уровни, состав, стоимость', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (19, '1. Предстартовая подготовка', 'Партнерства', 'Подготовить презентацию коммерческого предложения (КП) для партнеров', 'до старта продаж', 40000, 'Маркетинг|Дизайн'),
  (20, '1. Предстартовая подготовка', 'Партнерства', 'Сформировать базу потенциальных партнеров и целевой список контактов', 'до старта продаж', 30000, 'Отдел продаж|Маркетинг'),
  (21, '1. Предстартовая подготовка', 'Партнерства', 'Подготовить список компаний-«приманок» (якорных партнеров/участников для привлечения остальных)', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (22, '1. Предстартовая подготовка', 'Партнерства', 'Проработать возможность пакетных годовых партнерств (на цикл форумов компании)', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (23, '1. Предстартовая подготовка', 'Программа и спикеры', 'Выбрать подрядчика по работе со спикерами и программой (если привлекается внешний партнер)', 'до старта продаж', 300000, 'Программа'),
  (24, '1. Предстартовая подготовка', 'Программа и спикеры', 'Утвердить ключевые темы и архитектуру программы (количество и тематика сессий)', 'до старта продаж', 0, 'Программа'),
  (25, '1. Предстартовая подготовка', 'Программа и спикеры', 'Сформировать пул желаемых спикеров-экспертов', 'до старта продаж', 0, 'Программа|Маркетинг'),
  (26, '1. Предстартовая подготовка', 'Продажи', 'Подготовить и согласовать план продаж', 'до старта продаж', 0, 'Отдел продаж'),
  (27, '1. Предстартовая подготовка', 'Продажи', 'Сформировать отдел продаж: подбор и найм персонала', 'до старта продаж', 100000, 'Отдел продаж'),
  (28, '1. Предстартовая подготовка', 'Продажи', 'Разработать книку продаж (скрипты, базу возражений, презентация продукта, faq)', 'до старта продаж', 0, 'Отдел продаж'),
  (29, '1. Предстартовая подготовка', 'Продажи', 'Подготовить пакет раздаточных материалов (шаблоны писем, тексты для мессенджеров, презентации, КП)', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (30, '1. Предстартовая подготовка', 'Продажи', 'Настройка CRM: воронка, этапы, поля сделок, причины закрытия, роботы, подключены интеграции - почта, мессенджеры, телефония, создание документов', 'до старта продаж', 150000, 'Отдел продаж|Маркетинг'),
  (31, '1. Предстартовая подготовка', 'Продажи', 'Настроить телефонию - номера, запись звонков, интеграция с CRM', 'до старта продаж', 30000, 'Отдел продаж|Маркетинг'),
  (32, '1. Предстартовая подготовка', 'Продажи', 'Настроен сервис для e-mail-рассылок аутрич - домен, прогрев, шаблоны', 'до старта продаж', 25000, 'Отдел продаж|Маркетинг'),
  (33, '1. Предстартовая подготовка', 'Продажи', 'Разработана система мотивации - оклад, премии, проценты, KPI', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (34, '1. Предстартовая подготовка', 'Продажи', 'Разработана система мотивации - оклад, премии, проценты, KPI, писаны регламенты по скорости и качеству работы с клиентами', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (35, '1. Предстартовая подготовка', 'Продажи', 'Подготовлены чек-листы проверки качества работы менеджеров с клиентами - по ведению CRM, звонкам, переписке', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (36, '1. Предстартовая подготовка', 'Продажи', 'Проведено обучение менеджеров по техниккам продаж - отработаны скрипты, возражения', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (37, '1. Предстартовая подготовка', 'Продажи', 'Проведена аттестация менеджеров по продукту и продажам', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (38, '1. Предстартовая подготовка', 'Продажи', 'Подготовить базу для аутрич и обзвона', 'до старта продаж', 50000, 'Отдел продаж|Маркетинг'),
  (39, '1. Предстартовая подготовка', 'Маркетинг', 'Подготовить прототип сайта форума', 'до старта продаж', 150000, 'Маркетинг|Веб-разработчик'),
  (40, '1. Предстартовая подготовка', 'Маркетинг', 'Разработать поканальный план продвижения форума и медиабюджет', 'до старта продаж', 0, 'Маркетинг'),
  (41, '1. Предстартовая подготовка', 'Маркетинг', 'Выбрать и законтрактовать подрядчика по маркетинговому продвижению', 'до старта продаж', 500000, 'Маркетинг|Юрист'),
  (42, '1. Предстартовая подготовка', 'Команда', 'Сформировать организационную структуру проектной команды и зоны ответственности по направлениям', 'до старта продаж', 0, 'Ивент'),
  (43, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Старт продаж билетов участникам', 'контрольная точка, за 4 месяца', 0, 'Отдел продаж'),
  (44, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Старт продаж партнерского участия / спонсорских пакетов', 'контрольная точка, за 4 месяца', 0, 'Отдел продаж'),
  (45, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Утвердить инфопартнера (при наличии)', 'за 4 месяца до форума', 0, 'Маркетинг'),
  (46, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Запустить комплиментарные (бесплатные) приглашения ключевых для форума людей', 'с начала продаж', 0, 'Маркетинг'),
  (47, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Запустить на постоянной основе спецпредложения (пакетные цены «1+1», маркетинговые преференции)', 'с начала продаж, далее на регулярной основе', 0, 'Отдел продаж|Маркетинг'),
  (48, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Привлечь аутстаф-агентства и амбассадоров для продаж (по агентской схеме, за % от продаж)', 'за 3 месяца до форума', 0, 'Отдел продаж'),
  (49, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Проработать привлечение статусного представителя ключевого партнера для VIP-присутствия на форуме', 'за 3 месяца до форума', 0, 'Отдел продаж'),
  (50, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Проводить еженедельный мониторинг выполнения плана продаж и сверку с финансовой моделью', 'на всем протяжении этапа, еженедельно', 0, 'Отдел продаж|Финансы'),
  (51, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Завершить регистрацию / продажу билетов', 'за 1 день до форума', 0, 'Отдел продаж'),
  (52, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Еженедельные собрания с разбором звонков', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (53, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Еженедельный контроль качества работы менеджеров по чек-листам', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (54, '2. Продажи и орг. подготовка', 'Продажи и билеты', 'Обновлять книгу продаж по мере поступления новой информации, контроль раз в месяц', 'до старта продаж', 0, 'Отдел продаж|Маркетинг'),
  (55, '2. Продажи и орг. подготовка', 'Партнерства', 'Контролировать выполнение обязательств по партнерским пакетам (логотипы, упоминания, места на стендах)', 'на протяжении этапа', 0, 'Отдел продаж|Маркетинг'),
  (56, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Утвердить памятку спикера (регламент, требования к материалам, правила поведения на сцене)', 'за 8-9 недель до форума', 0, 'Программа'),
  (57, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Утвердить программу (названия сессий и их описание)', 'за 8-9 недель до форума', 0, 'Программа'),
  (58, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Утвердить кандидатуру модератора деловой программы', 'за 8-9 недель до форума', 0, 'Программа'),
  (59, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Заключить контракт(ы) с модератором(ами) и спикерами, если участвуют за гонорар', 'за 8 недель до форума', 300000, 'Юрист|Программа'),
  (60, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Вести коммуникацию со спикерами, проводить брифы', 'на протяжении этапа, до 30 дней', 0, 'Программа'),
  (61, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Завершить сбор информации о спикерах (фото, био, темы выступлений)', 'за 1 месяц до форума', 0, 'Программа|Маркетинг'),
  (62, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Утвердить итоговую программу мероприятия для публикации и рассылки участникам', 'за 6 недель до форума', 0, 'Программа|Маркетинг'),
  (63, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Утвердить базовый сценарий мероприятия, включая технический сценарный план для пультовой и команды и сценарии открытия/ключевых событий', 'за 10-12 дней до форума', 100000, 'Ивент'),
  (64, '2. Продажи и орг. подготовка', 'Программа и спикеры', 'Завершить сбор презентаций от спикеров', 'за 1 неделю до форума', 0, 'Программа'),
